// Original educational summaries; linked references remain on their publishers' sites.
import {earthGuides,earthLessons} from './grounding-content.js';
export const guides={
 power:{concept:'A potência útil é a energia convertida em trabalho por segundo. A potência ativa absorvida é maior quando há perdas; a aparente também incorpora o fator de potência.',use:'Informe tensão eficaz e use a tensão entre fases no trifásico. Rendimento e FP são razões: 92% deve ser escrito como 0,92. Se a potência já for elétrica de entrada, use rendimento 1.',example:'Com 15 kW úteis, 380 V, FP 0,85 e rendimento 0,92, a entrada é 16,304 kW e a corrente trifásica é aproximadamente 29,143 A.',pitfall:'Misturar potência mecânica com elétrica, ou tensão de fase com tensão de linha, altera a corrente calculada.'},
 ohm:{concept:'Um resistor ideal relaciona tensão e corrente de forma linear. A potência calculada é convertida em calor.',use:'Use a resistência em ohms. Compare a dissipação calculada com a potência nominal e as condições térmicas do componente.',example:'12 V sobre 100 Ω produzem 0,12 A e 1,44 W.',pitfall:'Um LED não é um resistor linear. Esta ferramenta não descreve a curva corrente × tensão de semicondutores.'},
 drop:{concept:'A resistência dos condutores provoca perda de tensão. Em dois condutores, o caminho de ida e volta é incluído pelo fator 2.',use:'Informe somente o comprimento de ida e a seção de um condutor. A resistividade deve representar o material e a temperatura de trabalho.',example:'220 V, 30 m, 20 A, 4 mm² e ρ=0,0175 resultam em 5,25 V de queda, ou 2,386%.',pitfall:'Dobrar o comprimento antes de informar o campo conta o retorno duas vezes. Queda de tensão pequena não comprova ampacidade suficiente.'},
 energy:{concept:'Energia depende da potência de entrada e do tempo de uso. kW mede potência; kWh mede energia acumulada.',use:'Use a potência média durante o funcionamento. Para equipamentos que ciclam, ajuste horas efetivas ou potência média.',example:'1.500 W por 4 h/dia durante 30 dias consomem 180 kWh. A R$ 0,95/kWh, o custo variável é R$ 171.',pitfall:'Uma conta de energia também pode incluir cobranças fixas e outros componentes que esta estimativa não calcula separadamente.'},
 pf:{concept:'A compensação reduz a parcela reativa indutiva. A potência ativa é mantida no modelo, enquanto a potência aparente diminui.',use:'Informe FP antes e depois, para a mesma carga ativa. O resultado em kvar é uma estimativa da compensação necessária.',example:'10 kW, passando de FP 0,8 para 1, exigem 7,5 kvar no modelo senoidal.',pitfall:'Capacitores não resolvem automaticamente a distorção harmônica. A solução real exige verificar ressonância e variação da carga.'},
 divider:{concept:'R1 está entre a fonte e a saída; R2 liga a saída ao terra. Uma carga adicional fica em paralelo com R2 e modifica a razão do divisor.',use:'Preencha a carga quando sua impedância DC for relevante. Campo vazio representa circuito aberto.',example:'10 V e dois resistores de 1 kΩ fornecem 5 V sem carga. Uma carga de 1 kΩ reduz a saída para 3,333 V.',pitfall:'Não use um divisor para alimentar uma carga de potência. A corrente consumida pela carga altera a tensão.'},
 led:{concept:'O resistor limita a corrente pela diferença entre a alimentação e a soma das quedas dos LEDs.',use:'Informe a corrente em mA e o Vf do datasheet no ponto de operação. O resultado é um valor teórico antes de escolher componentes comerciais.',example:'12 V, três LEDs de 2 V e 20 mA requerem 300 Ω, dissipando 0,12 W no resistor.',pitfall:'Vf muda com corrente e temperatura. Avalie a corrente de pior caso ao selecionar o resistor e sua potência nominal.'},
 rc:{concept:'A constante de tempo τ determina a rapidez da resposta ao degrau. A tensão do capacitor aproxima-se gradualmente da alimentação.',use:'Use capacitância em µF e tempo em ms. O cálculo começa com capacitor descarregado e não inclui resistência da fonte além da R informada.',example:'10 kΩ e 10 µF dão τ=100 ms. Depois de uma constante de tempo, a carga chega a cerca de 63,2% do valor final.',pitfall:'τ não é o tempo de carga completa. Após 5τ a carga está em aproximadamente 99,3%.'},
 resistors:{concept:'Na série, a corrente é comum e as resistências somam. No paralelo, a tensão é comum e as condutâncias somam.',use:'Informe os três resistores em ohms. Analise a potência em cada componente separadamente para o circuito real.',example:'Três resistores de 300 Ω equivalem a 900 Ω em série e 100 Ω em paralelo.',pitfall:'A resistência em paralelo deve ser menor que o menor resistor positivo. Essa comparação ajuda a conferir o resultado.'},
 adc:{concept:'Um ADC transforma uma faixa contínua de tensão em códigos discretos. A resolução define o tamanho ideal do intervalo de quantização.',use:'Esta ferramenta divide a referência por 2ᴺ e usa piso, saturando no código máximo. Confira a convenção do conversor real.',example:'12 bits e referência de 3,3 V dão 4.096 intervalos de 0,805664 mV. A entrada de 1,65 V gera código 2.048.',pitfall:'Mais bits não garantem a mesma precisão efetiva: ruído, referência, offset e não linearidade também importam.'},
 'drop-ac':{concept:'A projeção longitudinal da impedância incorpora resistência e reatância. O sinal da parcela reativa muda com o deslocamento da corrente.',use:'Use R e X em Ω/km por condutor, não a impedância total do circuito. Escolha carga indutiva ou capacitiva.',example:'Para 100 m, 80 A, 380 V trifásicos, R=0,524 Ω/km, X=0,08 Ω/km e FP=0,85 indutivo, a variação é aproximadamente 6,755 V.',pitfall:'A fórmula é aproximada. Quedas elevadas, desequilíbrios ou distorção pedem um modelo fasorial mais completo.'},
 'short-transformer':{concept:'A impedância percentual do transformador limita a corrente de uma falta trifásica. Quanto menor a impedância, maior a corrente estimada.',use:'Use potência nominal trifásica, tensão secundária entre fases e impedância percentual de placa.',example:'500 kVA, 380 V e Z=6% resultam em corrente nominal de 759,671 A e falta estimada de 12,661 kA.',pitfall:'Rede, cabos e contribuição de outras fontes mudam o resultado. Esta estimativa não é a corrente de pico nem uma seleção definitiva de disjuntor.'},
 adiabatic:{concept:'I²t representa a solicitação térmica acumulada por uma corrente constante. O limite do condutor é descrito por (kS)².',use:'Compare a solicitação com o limite usando k apropriado. Para dispositivos limitadores, obtenha I²t passante do fabricante.',example:'5 kA durante 0,2 s e k=115 exigem seção térmica de aproximadamente 19,444 mm². Uma seção de 25 mm² utiliza 60,491% do limite do modelo.',pitfall:'Esta seção térmica não é o dimensionamento completo. Ampacidade, queda, mínimos normativos e proteção devem ser verificados à parte.'},
 rlc:{concept:'Indutância e capacitância introduzem reatâncias de sinais opostos. Na ressonância, elas se cancelam no circuito série ideal.',use:'Use valores RMS para tensão e corrente; inclua em R as perdas série relevantes. O ângulo calculado é o da impedância.',example:'10 mH e 10 µF produzem ressonância em aproximadamente 503,292 Hz. Com R=10 Ω e 24 V na ressonância, a corrente é 2,4 A.',pitfall:'Tensões nos elementos podem superar a alimentação. O modelo ideal não prevê saturação do indutor ou limite de tensão do capacitor.'},
 motor:{concept:'A frequência e o número de polos definem a velocidade do campo girante. A diferença relativa para a rotação do eixo é o escorregamento.',use:'Informe potência mecânica no eixo, não potência elétrica absorvida. O torque calculado corresponde ao ponto de rotação informado.',example:'60 Hz e quatro polos dão 1.800 rpm síncronos. A 1.750 rpm, s=2,778%; 7,5 kW fornecem aproximadamente 40,926 N·m.',pitfall:'Torque nominal não equivale a torque de partida. Não use esta relação para prever toda a curva mecânica do motor.'},
 thd:{concept:'Componentes harmônicas aumentam a corrente RMS sem obedecer à relação simples entre potência e cosφ da fundamental.',use:'Informe amplitudes RMS medidas da fundamental e das três ordens disponíveis. O indicador calculado usa a fundamental como denominador.',example:'100 A na fundamental, 20 A na 3ª, 15 A na 5ª e 10 A na 7ª dão THD parcial de 26,926% e RMS parcial de 103,562 A.',pitfall:'Harmônicas omitidas tornam o indicador incompleto. THD e TDD têm denominadores distintos; esta ferramenta não calcula TDD.'},
 opamp:{concept:'A realimentação resistiva define o ganho ideal. O ganho de ruído é positivo e pode diferir do ganho de sinal inversor.',use:'Informe limites reais de saída do componente para a carga prevista. A calculadora exibe também a saída sem limitar para revelar saturação.',example:'No inversor, Rin=10 kΩ e Rf=100 kΩ dão Av=−10 e NG=11. Uma entrada de 0,2 V gera −2 V idealmente.',pitfall:'O resultado ideal exige região linear. Limites de modo comum e excursão de saída devem ser obtidos no datasheet.'},
 'opamp-speed':{concept:'A banda de pequeno sinal depende do ganho de ruído. Para sinais grandes, o slew rate limita a velocidade de variação da saída.',use:'Informe amplitude de pico da senoide e SR em V/µs. Trate os limites como fronteiras que precisam de margem.',example:'GBW=10 MHz e NG=11 dão cerca de 909,091 kHz. SR=5 V/µs com pico de 5 V limita a senoide a cerca de 159,155 kHz.',pitfall:'Operar no menor limite não garante baixa distorção. Estabilidade e carga também influenciam a resposta.'},
 buck:{concept:'O buck reduz tensão; o indutor armazena e libera energia a cada ciclo. O ripple é a diferença entre os picos de corrente.',use:'Compare Imin com zero e o pico com a corrente de saturação do indutor. O capacitor deve ser avaliado com ESR e tolerância reais.',example:'24→12 V, 100 kHz e 100 µH dão duty de 50% e ripple de 0,6 App. Com saída de 2 A, a corrente varia de 1,7 a 2,3 A.',pitfall:'Se Imin chegar a zero, a hipótese CCM perde validade. Os valores não substituem o projeto do controlador.'},
 boost:{concept:'O boost eleva tensão. Sem perdas, a corrente média da entrada cresce na proporção entre saída e entrada.',use:'Verifique pico e mínimo de corrente do indutor. A estimativa de ripple de tensão considera somente a capacitância.',example:'12→24 V a 1 A, 100 kHz e 100 µH dão duty de 50%, entrada média de 2 A e pico de 2,3 A.',pitfall:'Corrente de saída não é corrente do indutor. Perdas e dinâmica do controle precisam de análise adicional.'},
 'sallen-key':{concept:'A frequência natural define a posição dos polos; Q define amortecimento e eventual realce da resposta. O ponto de −3 dB depende de Q.',use:'Este modelo usa dois resistores iguais e dois capacitores iguais. O ganho K controla Q; para Butterworth, K=3−√2.',example:'R=10 kΩ e C=10 nF dão f₀≈1.591,549 Hz. Em Butterworth, Q≈0,7071 e o ponto de −3 dB coincide com f₀.',pitfall:'Para outros Q, chamar f₀ de frequência de corte pode induzir erro. Ganho próximo de 3 exige atenção às tolerâncias.'},
 thermal:{concept:'No modelo série, a elevação de temperatura é a potência dissipada multiplicada pela resistência térmica total.',use:'Use a potência convertida em calor e a resistência térmica do caminho físico correto. A margem é o limite informado menos a temperatura estimada.',example:'10 W, ambiente de 40 °C e resistências 2 + 0,5 + 4 °C/W dão Tj=105 °C. Para limite de 125 °C, θSA máximo é 6 °C/W.',pitfall:'θJA e ψJT não substituem θJC nesta rede. Um resultado aceitável exige validar a montagem e o fluxo de ar.'}
};

Object.assign(guides,earthGuides);
export const lessons=[...earthLessons,
 {id:'potencias',area:'Elétrica',title:'Potência: da placa do equipamento à corrente',level:'Fundamentos',minutes:5,tools:['power','pf','energy'],paragraphs:['Comece identificando o que a potência representa. Em um motor, a placa pode informar potência mecânica de saída; em uma carga resistiva, a potência absorvida é a que entra no balanço elétrico. Rendimento liga essas duas grandezas.','No regime senoidal, potência aparente S combina as parcelas ativa P e reativa Q. O fator de potência é P/S. Em sistemas trifásicos equilibrados, S=√3·Vlinha·Ilinha. Fora dessas hipóteses, a interpretação exige mais dados.','Procedimento: registre a origem dos dados, converta unidades, calcule a potência de entrada, encontre a corrente e confira a coerência com a placa. Para consumo, multiplique a potência média de entrada pelo tempo efetivo.'],exercise:'Uma carga monofásica absorve 2 kW a 220 V com FP 0,8. Qual é a corrente?',answer:'I = 2.000/(220×0,8) = 11,364 A. Rendimento 1 porque a potência já é de entrada.'},
 {id:'condutores',area:'Elétrica',title:'Condutores: queda de tensão e limite térmico',level:'Avançado',minutes:6,tools:['drop-ac','adiabatic','drop'],paragraphs:['Um condutor precisa atender a vários critérios simultaneamente. A variação de tensão descreve a condição na carga; o limite I²t descreve uma solicitação térmica de falta. Nenhum desses resultados, isoladamente, comprova o dimensionamento completo.','Para queda AC, use R e X por unidade de comprimento, na frequência e temperatura adequadas. O efeito da reatância depende do deslocamento da corrente. Informe comprimento de ida; o fator geométrico do modelo já representa o circuito.','Na verificação adiabática, k depende de material, isolação e temperaturas. Dispositivos limitadores devem ser avaliados pela energia passante declarada. Conclua a análise com ampacidade, método de instalação, agrupamento, proteção e requisitos aplicáveis obtidos em fontes normativas adequadas.'],exercise:'2 kA, 0,1 s e k=115: qual é a seção térmica teórica?',answer:'S = 2.000√0,1/115 ≈ 5,500 mm². Não é uma seção comercial nem o dimensionamento completo.'},
 {id:'curto',area:'Elétrica',title:'Curto-circuito: entender o alcance de uma estimativa',level:'Avançado',minutes:5,tools:['short-transformer','adiabatic'],paragraphs:['A corrente de falta depende da impedância entre a fonte e o ponto defeituoso. A estimativa de um transformador nos terminais usa sua impedância de placa e despreza a impedância da rede a montante.','A corrente simétrica RMS calculada não é a corrente de pico assimétrica. Local da falta, conexões, cabos, fontes em paralelo e contribuição de máquinas modificam o resultado.','Use a ferramenta para uma primeira comparação de ordem de grandeza. Um estudo de proteção deve avaliar correntes máximas e mínimas, tempos de eliminação, energia passante, capacidade de interrupção e coordenação. Não transforme a estimativa em uma seleção automática de equipamento.'],exercise:'Transformador de 100 kVA, 400 V e Z=5%: estime a falta trifásica nos terminais.',answer:'In ≈ 144,338 A; Icc ≈ 2,887 kA, dentro das hipóteses simplificadas.'},
 {id:'maquinas',area:'Elétrica',title:'Motores: rotação, torque e ponto de operação',level:'Avançado',minutes:4,tools:['motor','power'],paragraphs:['A velocidade síncrona é a velocidade do campo girante. No motor de indução em operação motora, o eixo gira abaixo dela e o escorregamento relaciona a diferença à velocidade síncrona.','Potência mecânica é torque vezes velocidade angular. Use a potência no eixo e converta rpm em rad/s antes da divisão. A relação descreve um ponto de funcionamento, sem prever torque de partida.','Ao comparar dados medidos com a placa, considere frequência de alimentação, carregamento e rendimento. Em acionamentos com inversor, a frequência pode mudar; fluxo, refrigeração e limites mecânicos também precisam ser conferidos.'],exercise:'Motor de 4 polos a 50 Hz gira a 1.450 rpm. Qual é o escorregamento?',answer:'ns = 1.500 rpm; s = (1.500−1.450)/1.500 = 3,333%.'},
 {id:'harmonicas',area:'Elétrica',title:'Harmônicas: por que cosφ não conta toda a história',level:'Avançado',minutes:5,tools:['thd','pf'],paragraphs:['Uma corrente não senoidal pode ser decomposta em fundamental e harmônicas. Por serem componentes ortogonais no período comum, suas parcelas RMS combinam-se pela soma dos quadrados.','A THD referenciada à fundamental compara o RMS das harmônicas com a fundamental. Aqui, apenas três ordens são informadas: o indicador é parcial e não representa uma medição completa.','Com tensão senoidal, a distorção da corrente reduz o fator de potência total em relação ao fator de deslocamento. Não generalize essa expressão quando a tensão também é distorcida. Para qualidade de energia, registre espectro, condições da medição e definição exata do indicador.'],exercise:'Fundamental de 100 A e somente uma harmônica de 30 A: quais são THD e RMS?',answer:'THD = 30%; Irms = √(100²+30²) ≈ 104,403 A.'},
 {id:'analogica',area:'Eletrônica',title:'Op amps: ganho, saturação e velocidade',level:'Avançado',minutes:6,tools:['opamp','opamp-speed'],paragraphs:['A realimentação negativa permite definir o ganho por uma rede resistiva, dentro da região linear. No inversor, o ganho de sinal pode ser negativo; o ganho de ruído é 1+Rf/Rin.','Depois do ganho DC, confira excursão de saída e faixa de modo comum. Para frequência, compare banda de pequeno sinal com a exigência de slew rate da amplitude de saída. São limitações distintas.','A sequência de análise é: ganho, condições DC, ganho de ruído, banda, slew rate, estabilidade e carga. A aproximação GBW/NG não substitui as curvas do componente nem a margem de fase.'],exercise:'Inversor com Rf/Rin=9 e GBW=10 MHz: qual ganho usar na estimativa de banda?',answer:'Ganho de ruído NG=10, portanto BW≈1 MHz. O ganho de sinal é −9.'},
 {id:'conversores',area:'Eletrônica',title:'Buck e boost: o que o modelo CCM permite calcular',level:'Avançado',minutes:6,tools:['buck','boost'],paragraphs:['CCM significa que a corrente do indutor permanece positiva durante todo o ciclo. Os modelos ideais usam o balanço de tensão no indutor para relacionar duty cycle e tensões.','No buck, a corrente média do indutor é a corrente de saída. No boost ideal, ela é a corrente de entrada. Compare o mínimo com zero para conferir CCM e o pico com os limites de corrente dos componentes.','Use estes resultados como ponto de partida. Seleção de semicondutores, perdas, saturação magnética, tolerância efetiva de capacitância, resposta a transientes, layout e compensação exigem análise própria do circuito e do controlador.'],exercise:'Buck ideal de 20 V para 5 V: qual é o duty? Boost ideal de 5 V para 20 V?',answer:'Buck: D=25%. Boost: D=75%. Os valores não incluem perdas.'},
 {id:'filtros',area:'Eletrônica',title:'Filtros: frequência natural, corte e ressonância',level:'Avançado',minutes:6,tools:['sallen-key','rlc','rc'],paragraphs:['Em primeira ordem, a constante de tempo conecta resposta temporal e frequência de corte. Em segunda ordem, o fator de qualidade Q acrescenta informação sobre amortecimento e formato da resposta.','No Sallen-Key de componentes iguais, R e C definem a frequência natural e K define Q. A frequência natural coincide com o ponto de −3 dB relativo ao ganho DC apenas no caso Butterworth.','No RLC série, a ressonância cancela a reatância líquida ideal. Perdas reais limitam o pico e podem mudar a resposta. Ao construir um filtro, avalie tolerâncias, parasitas, carregamento e limites do amplificador.'],exercise:'Sallen-Key de componentes iguais com K=1: qual é Q? f₀ é necessariamente o ponto de −3 dB?',answer:'Q=0,5. Não: neste caso f−3dB ≈ 0,643594×f₀.'},
 {id:'termica',area:'Eletrônica',title:'Térmica: converter perdas em temperatura',level:'Avançado',minutes:5,tools:['thermal','led','ohm'],paragraphs:['O ponto de partida é a potência dissipada em calor, não a potência entregue à carga. Em uma rede térmica série, cada resistência provoca uma elevação de temperatura proporcional ao fluxo de calor.','A soma θJC+θCS+θSA faz sentido quando o caminho pelo dissipador é predominante e o parâmetro de encapsulamento representa esse caminho. Não misture caracterizações térmicas com condições de ensaio diferentes.','Adote uma temperatura limite de projeto e compare a margem. Fluxo de ar, interface, montagem e outros componentes alteram o comportamento real. O modelo é de regime permanente; pulsos exigem impedância térmica transitória e curvas do fabricante.'],exercise:'5 W sobre uma resistência térmica total de 10 °C/W, a 30 °C ambiente: estime a junção.',answer:'Tj=30+5×10=80 °C, sob as hipóteses da rede série.'},
 {id:'medicao',area:'Eletrônica',title:'Medição: divisor, referência e quantização',level:'Fundamentos',minutes:5,tools:['divider','adc'],paragraphs:['Antes de ligar um sinal a um ADC, ajuste sua faixa e avalie a carga sobre o divisor. A impedância de entrada pode variar dinamicamente durante a aquisição; a resistência DC equivalente não descreve todo esse processo.','A referência define a escala. O número de bits define a granularidade ideal, enquanto ruído, tolerâncias, offset e não linearidade influenciam a precisão real.','Registre a convenção de quantização e o instante de amostragem. Confira a faixa admissível dos pinos, o tempo de aquisição e a estabilidade da referência no datasheet do conversor.'],exercise:'8 bits e referência de 2,56 V: qual é o LSB ideal?',answer:'LSB=2,56/256=0,01 V, ou 10 mV.'}
];
export const glossary=[['RMS','Valor eficaz: raiz da média do quadrado da grandeza. Relaciona uma corrente periódica ao efeito térmico equivalente.'],['FP','Fator de potência total: razão entre potência ativa e aparente, na definição adotada.'],['cosφ₁','Fator de deslocamento da fundamental; não incorpora sozinho a distorção harmônica.'],['CCM / DCM','Condução contínua / descontínua da corrente do indutor em conversores.'],['GBW','Produto ganho × largura de banda na aproximação de polo dominante.'],['Ganho de ruído','Ganho usado na avaliação de realimentação, ruído e banda; pode diferir do ganho de sinal.'],['Slew rate','Máxima taxa de variação da tensão de saída, normalmente em V/µs.'],['I²t','Integral da corrente ao quadrado no tempo; energia específica passante em A²·s.'],['Q','Fator de qualidade: descreve amortecimento e seletividade em modelos de segunda ordem.'],['θJC / θCS / θSA','Resistências térmicas entre junção, encapsulamento, dissipador e ambiente.'],['LSB','Menor intervalo ideal de quantização na convenção adotada pelo conversor.'],['THD / TDD','Indicadores de distorção com referências diferentes; informe sempre o denominador utilizado.']];
